.faq-q{width:100%;display:flex;align-items:center;justify-content:space-between;gap:16px;
  padding:20px 24px;background:none;border:0;cursor:pointer;text-align:left;
  font-family:var(--font-body);font-size:16.5px;font-weight:700;color:var(--ink)}
.faq-chev{flex:none;color:var(--gold-bright);font-size:14px;transition:transform .25s}
.faq-item.open .faq-chev{transform:rotate(180deg)}
.faq-a{max-height:0;overflow:hidden;transition:max-height .32s ease}
.faq-a-in{padding:0 24px 20px}
.faq-a-in p{color:var(--muted);line-height:1.75;font-size:15.5px;margin:0}
.faq-a-in a{color:var(--gold-bright);font-weight:600}
.faq-inline-btn{display:inline-block;margin-top:12px;padding:9px 18px;border-radius:999px;
  background:var(--gold-grad);color:#15100a;font-weight:700;font-size:14px;text-decoration:none}
.faq-empty{text-align:center;color:var(--muted);padding:40px 0;display:none}
.faq-cat{scroll-margin-top:90px}
.faq-a-in .faq-list-num{margin:10px 0 16px;padding-left:22px;color:var(--muted);line-height:1.75;font-size:15.5px}
.faq-a-in .faq-list-num li{margin-bottom:6px}
.faq-a-in h4.faq-sub{margin:20px 0 4px;color:var(--gold-bright);font-family:var(--font-display);font-size:16px;letter-spacing:.02em}
.faq-a-in p.faq-cite-other{margin:10px 0;padding:12px 16px;border-left:3px solid var(--line-2);background:var(--panel-2);
  color:var(--ink-soft);font-size:14.5px;line-height:1.7;border-radius:0 10px 10px 0}
.faq-a-in p.faq-cite-other em{color:var(--muted);font-style:italic}
.faq-a-in p+p{margin-top:12px}
a.vref{color:var(--gold-bright);font-weight:700;text-decoration:none;border-bottom:1px dashed var(--gold);
  cursor:pointer;white-space:nowrap}
a.vref:hover{color:var(--gold);border-bottom-style:solid}
cite.vref-cite{cursor:pointer;text-decoration:none;border-bottom:1px dashed currentColor}

.vp-overlay{position:fixed;inset:0;z-index:9999;display:none;align-items:center;justify-content:center;
  padding:20px;background:rgba(10,8,5,.6);backdrop-filter:blur(3px)}
.vp-overlay.open{display:flex}
.vp-card{position:relative;width:100%;max-width:480px;max-height:82vh;display:flex;flex-direction:column;
  background:linear-gradient(180deg,var(--panel),var(--panel-2));border:1px solid var(--line-2);
  border-radius:var(--radius);box-shadow:var(--shadow);overflow:hidden}
.vp-close{position:absolute;top:14px;right:14px;z-index:2;width:32px;height:32px;border-radius:50%;
  border:1px solid var(--line-2);background:var(--panel-2);color:var(--ink);font-size:18px;line-height:1;
  cursor:pointer;display:flex;align-items:center;justify-content:center}
.vp-close:hover{border-color:var(--gold);color:var(--gold-bright)}
.vp-scroll{padding:22px 24px 8px;overflow-y:auto}
.vp-block{padding-bottom:18px;margin-bottom:18px;border-bottom:1px solid var(--line)}
.vp-block:last-child{border-bottom:0;margin-bottom:0}
.vp-chip{display:inline-block;padding:5px 14px;border-radius:999px;background:var(--gold-grad);
  color:#15100a;font-weight:800;font-size:13px;letter-spacing:.02em;margin-bottom:12px}
.vp-ar{direction:rtl;text-align:right;font-family:var(--font-ar);font-size:22px;line-height:2;color:var(--ink);margin-bottom:12px}
.vp-en{font-size:15.5px;line-height:1.7;color:var(--ink-soft);margin:0 0 8px}
.vp-ta{font-family:var(--font-body);font-size:14px;line-height:1.75;color:var(--muted);margin:0}
.vp-foot{padding:14px 24px;text-align:right;border-top:1px solid var(--line-2);background:var(--panel-2)}
.vp-open{color:var(--gold-bright);font-weight:700;font-size:14px;text-decoration:none}
.vp-open:hover{color:var(--gold)}
</style>

